package com.englishhero.reading.translation;
import java.util.*;import java.time.*;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;
import com.englishhero.practice.review.*;import static com.englishhero.reading.translation.SelectionTranslationDtos.*;
@Service
public class SelectionTranslationJobs {
 private final SelectionTranslationMapper m;private final Clock clock;private final BaiduTranslationProperties baidu;
 public SelectionTranslationJobs(SelectionTranslationMapper m,Clock c,BaiduTranslationProperties baidu){this.m=m;clock=c;this.baidu=baidu;}
 @Transactional(isolation=Isolation.READ_COMMITTED)public void recover(){var now=clock.instant();var rows=m.sql().query("SELECT * FROM reading_selection_translation WHERE (status='RUNNING' AND lease_until<?) OR (status='QUEUED' AND created_at<?) FOR UPDATE SKIP LOCKED",m.jobs(),java.sql.Timestamp.from(now),java.sql.Timestamp.from(now.minusSeconds(120)));for(var j:rows)settle(j,"QUEUED".equals(j.status())?"QUEUE_EXPIRED":"OUTCOME_UNKNOWN",null,null,null,"QUEUED".equals(j.status())?0:j.reserve());}
 @Transactional(isolation=Isolation.READ_COMMITTED)public Optional<Job> claim(){m.sql().update("INSERT INTO practice_ai_daily_budget(budget_day) VALUES('1970-01-02') ON DUPLICATE KEY UPDATE budget_day=VALUES(budget_day)");m.sql().queryForObject("SELECT used_microusd FROM practice_ai_daily_budget WHERE budget_day='1970-01-02' FOR UPDATE",Long.class);if(m.sql().queryForObject("SELECT COUNT(*) FROM reading_selection_translation WHERE status='RUNNING'",Long.class)>0)return Optional.empty();var rows=m.sql().query("SELECT * FROM reading_selection_translation WHERE status='QUEUED' ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED",m.jobs());if(rows.isEmpty())return Optional.empty();var j=rows.getFirst();if(!Boolean.TRUE.equals(m.sql().queryForObject("SELECT enabled FROM identity_user WHERE id=?",Boolean.class,j.user()))){settle(j,"ACCOUNT_DISABLED",null,null,null,0);return Optional.empty();}if(!rollMonth(j))return Optional.empty();String lease=UUID.randomUUID().toString();m.sql().update("UPDATE reading_selection_translation SET status='RUNNING',lease_token=?,lease_until=? WHERE id=?",lease,java.sql.Timestamp.from(clock.instant().plusSeconds(60)),j.id());return m.sql().query("SELECT * FROM reading_selection_translation WHERE id=?",m.jobs(),j.id()).stream().findFirst();}
 private boolean rollMonth(Job j){
  if(!BaiduTranslationProperties.MODEL.equals(j.model()))return true;
  var month=clock.instant().atZone(ZoneId.of("Asia/Shanghai")).toLocalDate().withDayOfMonth(1);if(month.equals(j.quotaMonth()))return true;
  m.sql().queryForObject("SELECT used_characters FROM reading_baidu_monthly_quota WHERE month_start=? FOR UPDATE",Long.class,j.quotaMonth());
  m.sql().update("INSERT INTO reading_baidu_monthly_quota(month_start) VALUES(?) ON DUPLICATE KEY UPDATE month_start=VALUES(month_start)",month);
  long used=m.sql().queryForObject("SELECT used_characters FROM reading_baidu_monthly_quota WHERE month_start=? FOR UPDATE",Long.class,month);
  if(j.characters()>Math.max(0,baidu.getMonthlyCharacterLimit())-used){settle(j,"BAIDU_CHARACTER_QUOTA",null,null,null,0);return false;}
  m.sql().update("UPDATE reading_baidu_monthly_quota SET used_characters=used_characters-? WHERE month_start=?",j.characters(),j.quotaMonth());
  m.sql().update("UPDATE reading_baidu_monthly_quota SET used_characters=used_characters+? WHERE month_start=?",j.characters(),month);
  m.sql().update("UPDATE reading_selection_translation SET quota_month=? WHERE id=?",month,j.id());return true;
 }
 private boolean current(Job j){return !m.sql().query("SELECT * FROM reading_selection_translation WHERE id=? AND status='RUNNING' AND lease_token=? AND lease_until>? FOR UPDATE",m.jobs(),j.id(),j.lease(),java.sql.Timestamp.from(clock.instant())).isEmpty();}
 @Transactional(isolation=Isolation.READ_COMMITTED)public void complete(Job j,DeepSeekReviewClient.TranslationResponse result){if(!current(j))return;long settled=PracticeReviewBudget.knownUsage(result.inputTokens(),result.outputTokens())?Math.min(j.reserve(),PracticeReviewBudget.cost(result.inputTokens(),result.outputTokens())):j.reserve();settle(j,null,result.translation(),result.inputTokens(),result.outputTokens(),settled);}
 @Transactional(isolation=Isolation.READ_COMMITTED)public void completeBaidu(Job j,BaiduTranslationClient.Result result){if(!current(j))return;settle(j,null,result.translation(),null,null,0);}
 @Transactional(isolation=Isolation.READ_COMMITTED)public void failBaidu(Job j,BaiduTranslationClient.Failure failure){if(!current(j))return;settle(j,failure.code,null,null,null,0);}
 @Transactional(isolation=Isolation.READ_COMMITTED)public void fail(Job j,DeepSeekReviewClient.Failure failure){if(!current(j))return;long settled=failure.definitelyUnsent?0:PracticeReviewBudget.knownUsage(failure.inputTokens,failure.outputTokens)?Math.min(j.reserve(),PracticeReviewBudget.cost(failure.inputTokens,failure.outputTokens)):j.reserve();settle(j,failure.code,null,failure.inputTokens,failure.outputTokens,settled);}
 private void settle(Job j,String error,String text,Long input,Long output,long settled){m.sql().update("UPDATE reading_selection_translation SET status=?,error_code=?,translated_text=?,analysis_json=?,input_tokens=?,output_tokens=?,settled_microusd=?,completed_at=? WHERE id=?",error==null?"SUCCEEDED":"FAILED",error,"GRAMMAR".equals(j.mode())?null:text,"GRAMMAR".equals(j.mode())?text:null,input,output,settled,java.sql.Timestamp.from(clock.instant()),j.id());if(BaiduTranslationProperties.MODEL.equals(j.model())){if(error!=null&&(BaiduTranslationJobsSupport.unsent(error)||"QUEUED".equals(j.status())))m.sql().update("UPDATE reading_baidu_monthly_quota SET used_characters=used_characters-? WHERE month_start=?",j.characters(),j.quotaMonth());}else m.sql().update("UPDATE practice_ai_daily_budget SET used_microusd=used_microusd-?+? WHERE budget_day=?",j.reserve(),settled,j.day());}
}
